//! Integration tests for the Ses Dikte pipeline.
//!
//! These run the REAL bundled FFmpeg/ffprobe and (where noted) the REAL
//! whisper.cpp + model against synthetic fixtures generated by
//! `scripts/generate-speech-fixtures.ps1`. They skip with a visible message
//! when the engines or fixtures are not staged on the machine; set
//! `MEB_REQUIRE_SPEECH_ENGINES=1` to turn a skip into a failure (used for the
//! acceptance run).

use super::job::JobRegistry;
use super::limits::{SpeechLimits, DEFAULT_LIMITS};
use super::pipeline::{self, JobState};
use crate::engines::audio_prep;
use crate::engines::speech::{Segment, SpeechEngine, SpeechEngineInfo, TranscribeRequest, Transcript, WhisperCppEngine};
use crate::engines::speech_error::{SpeechError, SpeechErrorCode};
use std::path::{Path, PathBuf};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};

// ---------------------------------------------------------------- helpers ----

fn fixtures_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/speech/generated")
}

fn require() -> bool {
    std::env::var("MEB_REQUIRE_SPEECH_ENGINES").map(|v| v == "1").unwrap_or(false)
}

/// Some(path) when the fixture exists; otherwise skip (or fail when required).
fn fixture(name: &str) -> Option<PathBuf> {
    let p = fixtures_dir().join(name);
    if p.is_file() {
        return Some(p);
    }
    assert!(!require(), "required fixture missing: {name} (run scripts/generate-speech-fixtures.ps1)");
    eprintln!("SKIP: fixture {name} not generated");
    None
}

fn audio_prep_ready() -> bool {
    let ok = audio_prep::status().is_ok();
    assert!(ok || !require(), "audio prep engine not staged/valid");
    if !ok {
        eprintln!("SKIP: bundled FFmpeg not staged");
    }
    ok
}

fn whisper_ready() -> Option<WhisperCppEngine> {
    match WhisperCppEngine::load() {
        Ok(e) => Some(e),
        Err(e) => {
            assert!(!require(), "speech engine not usable: {e}");
            eprintln!("SKIP: speech engine not usable: {}", e.code.as_str());
            None
        }
    }
}

/// Records what the pipeline handed to the engine, so tests can assert on the
/// preprocessed audio and on cleanup without running Whisper.
#[derive(Default)]
struct FakeEngine {
    calls: AtomicUsize,
    seen_job_dirs: Mutex<Vec<PathBuf>>,
    seen_wav_secs: Mutex<Vec<f64>>,
    normalized_ok: Mutex<Vec<bool>>,
    fail_first_n: AtomicUsize,
    delay_ms: u64,
}

impl SpeechEngine for FakeEngine {
    fn info(&self) -> SpeechEngineInfo {
        SpeechEngineInfo {
            engine_name: "fake".into(),
            engine_version: "0".into(),
            model_id: "fake".into(),
            languages: vec!["tr".into(), "auto".into()],
            supports_timestamps: true,
            supports_progress: false,
        }
    }
    fn transcribe(
        &self,
        req: &TranscribeRequest<'_>,
        cancel: &AtomicBool,
        _p: &(dyn Fn(Option<u8>) + Sync),
    ) -> Result<Transcript, SpeechError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        self.seen_job_dirs.lock().unwrap().push(req.job_dir.to_path_buf());
        let wav = req.job_dir.join(req.wav_name);
        let info = crate::engines::audio_wav::read_wav_info(&wav);
        self.normalized_ok.lock().unwrap().push(info.map(|i| i.is_speech_normalized()).unwrap_or(false));
        self.seen_wav_secs.lock().unwrap().push(info.map(|i| i.duration_secs()).unwrap_or(0.0));
        if self.delay_ms > 0 {
            let steps = self.delay_ms / 20;
            for _ in 0..steps {
                if cancel.load(Ordering::SeqCst) {
                    return Err(SpeechError::new(SpeechErrorCode::SpeechCancelled));
                }
                std::thread::sleep(std::time::Duration::from_millis(20));
            }
        }
        if self.fail_first_n.load(Ordering::SeqCst) > 0 {
            self.fail_first_n.fetch_sub(1, Ordering::SeqCst);
            return Err(SpeechError::new(SpeechErrorCode::SpeechTranscriptionFailed).with_detail("simulated failure"));
        }
        Ok(Transcript {
            language: req.language.to_string(),
            segments: vec![Segment { start_ms: 0, end_ms: 1000, text: "Merhaba dünya.".into() }],
            timestamps_available: true,
        })
    }
}

fn run(path: &Path, lang: &str, engine: &dyn SpeechEngine) -> Result<Transcript, SpeechError> {
    run_with(path, lang, &DEFAULT_LIMITS, engine, &AtomicBool::new(false))
}

fn run_with(
    path: &Path,
    lang: &str,
    limits: &SpeechLimits,
    engine: &dyn SpeechEngine,
    cancel: &AtomicBool,
) -> Result<Transcript, SpeechError> {
    pipeline::run_file_job(&path.to_string_lossy(), lang, limits, engine, cancel, &|_, _| {})
}

fn norm(s: &str) -> String {
    s.to_lowercase()
        .chars()
        .map(|c| match c {
            'ı' => 'i',
            'ş' => 's',
            'ğ' => 'g',
            'ü' => 'u',
            'ö' => 'o',
            'ç' => 'c',
            c if c.is_alphanumeric() || c == ' ' => c,
            _ => ' ',
        })
        .collect()
}

/// Real-Whisper tests are CPU-heavy and (for the cancel test) count OS processes,
/// so they must not overlap each other.
static REAL_WHISPER: Mutex<()> = Mutex::new(());
fn real_lock() -> std::sync::MutexGuard<'static, ()> {
    REAL_WHISPER.lock().unwrap_or_else(|e| e.into_inner())
}

fn tmp_dir() -> PathBuf {
    let d = std::env::temp_dir().join(format!("meb_speech_it_{}", uuid::Uuid::new_v4()));
    std::fs::create_dir_all(&d).unwrap();
    d
}

fn whisper_processes() -> usize {
    let out = std::process::Command::new("tasklist")
        .args(["/FI", "IMAGENAME eq whisper-cli.exe", "/NH"])
        .output()
        .map(|o| String::from_utf8_lossy(&o.stdout).to_string())
        .unwrap_or_default();
    out.matches("whisper-cli.exe").count()
}

// ------------------------------------------------- formats (real FFmpeg) ----

#[test]
fn every_accepted_format_preprocesses_to_normalized_wav_with_a_real_fixture() {
    if !audio_prep_ready() {
        return;
    }
    // Extension -> fixture. An extension is only "supported" because its row
    // here passes; audio_prep::ACCEPTED_EXTENSIONS must equal this list.
    let table = [
        ("wav", "tr_speech.wav"),
        ("mp3", "tr_speech.mp3"),
        ("m4a", "tr_speech.m4a"),
        ("aac", "tr_speech.aac"),
        ("flac", "tr_speech.flac"),
        ("ogg", "tr_speech.ogg"),
        ("ogg", "tr_speech_opus.ogg"), // Ogg container with Opus, the other common .ogg
    ];
    let mut covered: Vec<&str> = table.iter().map(|(e, _)| *e).collect();
    covered.sort();
    covered.dedup();
    let mut accepted: Vec<&str> = audio_prep::ACCEPTED_EXTENSIONS.to_vec();
    accepted.sort();
    assert_eq!(covered, accepted, "every accepted extension needs a passing fixture (and vice versa)");

    for (ext, name) in table {
        let Some(path) = fixture(name) else { return };
        let engine = FakeEngine::default();
        let t = run(&path, "tr", &engine).unwrap_or_else(|e| panic!("{name} ({ext}) failed: {e}"));
        assert_eq!(t.segments.len(), 1);
        assert_eq!(engine.normalized_ok.lock().unwrap().as_slice(), &[true], "{name}: not 16k mono PCM16");
        let secs = engine.seen_wav_secs.lock().unwrap()[0];
        assert!((8.0..=16.0).contains(&secs), "{name}: implausible duration {secs}s (source is ~10s of speech)");
    }
}

#[test]
fn source_with_unicode_spaces_and_shell_metacharacters_in_its_name_is_handled_as_data() {
    if !audio_prep_ready() {
        return;
    }
    let Some(src) = fixture("tr_speech.mp3") else { return };
    let d = tmp_dir();
    let evil = d.join("toplantı kaydı & (özel) ; 'x' $HOME `id` %PATH% ş.mp3");
    std::fs::copy(&src, &evil).unwrap();
    let engine = FakeEngine::default();
    run(&evil, "tr", &engine).expect("metacharacters/Unicode in the file name must be inert");
    assert_eq!(engine.calls.load(Ordering::SeqCst), 1);
    let _ = std::fs::remove_dir_all(d);
}

