#[test]
fn zero_byte_file_is_rejected_before_any_process() {
    let d = tmp_dir();
    let p = d.join("empty.mp3");
    std::fs::write(&p, b"").unwrap();
    let engine = FakeEngine::default();
    let e = run(&p, "tr", &engine).unwrap_err();
    assert_eq!(e.code, SpeechErrorCode::SpeechInputUnsupported);
    assert!(e.message().contains("boş"));
    assert_eq!(engine.calls.load(Ordering::SeqCst), 0);
    let _ = std::fs::remove_dir_all(d);
}

#[test]
fn unsupported_extensions_are_rejected_without_opening_the_file() {
    let d = tmp_dir();
    for name in ["notes.txt", "clip.mp4", "clip.wma", "clip.opus", "tool.exe", "song.mp3.exe", "noext"] {
        let p = d.join(name);
        std::fs::write(&p, b"RIFF....WAVE").unwrap();
        let engine = FakeEngine::default();
        let e = run(&p, "tr", &engine).unwrap_err();
        assert_eq!(e.code, SpeechErrorCode::SpeechInputUnsupported, "{name}");
        assert!(e.message().contains("WAV, MP3, M4A, AAC, FLAC, OGG"));
        assert_eq!(engine.calls.load(Ordering::SeqCst), 0);
    }
    let _ = std::fs::remove_dir_all(d);
}

#[test]
fn remote_urls_and_unc_paths_are_never_accepted() {
    let engine = FakeEngine::default();
    for bad in [
        "http://example.com/a.mp3",
        "https://example.com/a.wav",
        "ftp://x/a.mp3",
        "rtmp://x/a.flac",
        "\\\\server\\share\\a.mp3",
        "//server/share/a.mp3",
        "file:///C:/a.mp3",
    ] {
        let e = pipeline::run_file_job(bad, "tr", &DEFAULT_LIMITS, &engine, &AtomicBool::new(false), &|_, _| {}).unwrap_err();
        assert_eq!(e.code, SpeechErrorCode::SpeechInputUnsupported, "{bad}");
    }
    assert_eq!(engine.calls.load(Ordering::SeqCst), 0);
}

#[test]
fn missing_file_is_reported_as_not_found_in_turkish() {
    let engine = FakeEngine::default();
    let e = run(Path::new("C:\\definitely\\not\\here\\a.mp3"), "tr", &engine).unwrap_err();
    assert_eq!(e.code, SpeechErrorCode::SpeechInputNotFound);
    assert!(e.message().contains("erişilemiyor"));
}

#[test]
fn corrupt_mp3_fails_with_a_structured_turkish_error_and_leaves_no_temp_files() {
    if !audio_prep_ready() {
        return;
    }
    let d = tmp_dir();
    let p = d.join("corrupt.mp3");
    // pseudo-random garbage with an ID3 header so it "looks like" an MP3
    let mut junk = b"ID3\x03\x00\x00\x00\x00\x00\x00".to_vec();
    let mut x: u32 = 0x1234_5678;
    for _ in 0..40_000 {
        x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
        junk.push((x >> 24) as u8);
    }
    std::fs::write(&p, junk).unwrap();
    let engine = FakeEngine::default();
    let e = run(&p, "tr", &engine).unwrap_err();
    assert!(
        matches!(e.code, SpeechErrorCode::SpeechPreprocessFailed | SpeechErrorCode::SpeechInputUnsupported),
        "unexpected code {:?}",
        e.code
    );
    assert!(e.message().ends_with('.'));
    assert!(!e.message().to_lowercase().contains("ffmpeg"));
    assert_eq!(engine.calls.load(Ordering::SeqCst), 0);
    let _ = std::fs::remove_dir_all(d);
}

#[test]
fn truncated_real_mp3_is_handled_without_crashing() {
    if !audio_prep_ready() {
        return;
    }
    let Some(src) = fixture("tr_speech.mp3") else { return };
    let d = tmp_dir();
    let p = d.join("truncated.mp3");
    let bytes = std::fs::read(&src).unwrap();
    std::fs::write(&p, &bytes[..bytes.len() / 3]).unwrap();
    let engine = FakeEngine::default();
    // Either a shorter decode succeeds or a structured error is returned; both are acceptable, a panic/hang is not.
    match run(&p, "tr", &engine) {
        Ok(_) => assert_eq!(engine.calls.load(Ordering::SeqCst), 1),
        Err(e) => assert!(matches!(e.code, SpeechErrorCode::SpeechPreprocessFailed | SpeechErrorCode::SpeechNoSpeechDetected)),
    }
    let _ = std::fs::remove_dir_all(d);
}

