// -------------------------------------------------------------- limits ------

#[test]
fn oversized_input_is_rejected_gracefully_before_processing() {
    let Some(p) = fixture("tr_speech.wav") else { return };
    let tiny = SpeechLimits { max_input_bytes: 1000, ..DEFAULT_LIMITS };
    let engine = FakeEngine::default();
    let e = run_with(&p, "tr", &tiny, &engine, &AtomicBool::new(false)).unwrap_err();
    assert_eq!(e.code, SpeechErrorCode::SpeechResourceLimit);
    assert!(e.message().contains("çok büyük"));
    assert_eq!(engine.calls.load(Ordering::SeqCst), 0);
}

#[test]
fn over_long_audio_is_rejected_using_probed_and_measured_duration() {
    if !audio_prep_ready() {
        return;
    }
    let short = SpeechLimits { max_audio_secs: 2, ..DEFAULT_LIMITS };
    // WAV states its duration -> caught at the probe stage.
    // ADTS AAC states none -> caught after normalization from the decoded samples.
    for name in ["tr_speech.wav", "tr_speech.aac", "tr_speech.mp3"] {
        let Some(p) = fixture(name) else { return };
        let engine = FakeEngine::default();
        let e = run_with(&p, "tr", &short, &engine, &AtomicBool::new(false)).unwrap_err();
        assert_eq!(e.code, SpeechErrorCode::SpeechResourceLimit, "{name}");
        assert!(e.message().contains("çok uzun"), "{name}");
        assert_eq!(engine.calls.load(Ordering::SeqCst), 0, "{name}");
    }
}

#[test]
fn the_duration_limit_boundary_accepts_exactly_the_limit_and_rejects_above() {
    // pure boundary check on the policy object (file-independent)
    let l = DEFAULT_LIMITS;
    assert!(l.check_duration(l.max_audio_secs as f64).is_ok());
    assert!(l.check_duration(l.max_audio_secs as f64 + 0.5).is_err());
}

