#[test]
fn real_cancel_during_transcription_kills_whisper_and_cleans_up() {
    let _serial = real_lock();
    if !audio_prep_ready() {
        return;
    }
    let Some(engine) = whisper_ready() else { return };
    let Some(p) = fixture("tr_speech_long.wav") else { return };
    let before = whisper_processes();
    let cancel = AtomicBool::new(false);
    let seen_transcribing = AtomicBool::new(false);
    let started = std::time::Instant::now();
    let res = std::thread::scope(|s| {
        s.spawn(|| {
            // wait until transcription really started, then let it run briefly
            while !seen_transcribing.load(Ordering::SeqCst) {
                std::thread::sleep(std::time::Duration::from_millis(50));
                if started.elapsed().as_secs() > 60 {
                    break;
                }
            }
            std::thread::sleep(std::time::Duration::from_secs(4));
            cancel.store(true, Ordering::SeqCst);
        });
        pipeline::run_file_job(&p.to_string_lossy(), "tr", &DEFAULT_LIMITS, &engine, &cancel, &|s, _| {
            if s == JobState::Transcribing {
                seen_transcribing.store(true, Ordering::SeqCst);
            }
        })
    });
    let e = res.unwrap_err();
    assert_eq!(e.code, SpeechErrorCode::SpeechCancelled);
    let mut after = whisper_processes();
    for _ in 0..30 {
        if after <= before {
            break;
        }
        std::thread::sleep(std::time::Duration::from_millis(100));
        after = whisper_processes();
    }
    assert!(after <= before, "a whisper-cli process is still running after cancel ({after} > {before})");
    eprintln!("[cancel] cancelled after {:.1}s total", started.elapsed().as_secs_f64());
}

#[test]
fn real_long_audio_ten_minutes_transcribes_without_blocking() {
    let _serial = real_lock();
    if std::env::var("MEB_RUN_LONG_SPEECH_TEST").map(|v| v != "1").unwrap_or(true) {
        eprintln!("SKIP: long test (set MEB_RUN_LONG_SPEECH_TEST=1)");
        return;
    }
    if !audio_prep_ready() {
        return;
    }
    let Some(engine) = whisper_ready() else { return };
    let Some(p) = fixture("tr_speech_long.wav") else { return };
    let last_pct = Mutex::new(None::<u8>);
    let started = std::time::Instant::now();
    let t = pipeline::run_file_job(&p.to_string_lossy(), "tr", &DEFAULT_LIMITS, &engine, &AtomicBool::new(false), &|_, pct| {
        if pct.is_some() {
            *last_pct.lock().unwrap() = pct;
        }
    })
    .unwrap();
    let secs = started.elapsed().as_secs_f64();
    let words = t.plain_text().split_whitespace().count();
    eprintln!("[long] {} segments, {words} words in {secs:.0}s; last progress {:?}", t.segments.len(), last_pct.lock().unwrap());
    assert!(t.segments.len() > 20);
    assert!(norm(&t.plain_text()).contains("siber"));
}

