#[test]
fn whisper_argv_is_structured_local_and_contains_no_shell_or_url() {
    let Some(engine) = whisper_ready() else { return };
    let d = tmp_dir();
    let req = TranscribeRequest { job_dir: &d, wav_name: "norm.wav", language: "tr" };
    let args = engine.build_args(&req, "m/ggml-x.bin", "transcript");
    for a in &args {
        let l = a.to_lowercase();
        assert!(!l.contains("://") && !l.contains("http"), "URL-ish arg: {a}");
        assert!(!["cmd", "cmd.exe", "powershell", "sh", "bash", "/c", "-command"].contains(&l.as_str()), "shell arg: {a}");
    }
    assert!(args.windows(2).any(|w| w[0] == "-f" && w[1] == "norm.wav"), "input must be the generated relative name");
    assert!(args.windows(2).any(|w| w[0] == "-l" && w[1] == "tr"));
    assert!(args.contains(&"-ng".to_string()), "GPU backends must stay off");
    let m = args.windows(2).find(|w| w[0] == "-m").map(|w| w[1].clone()).unwrap();
    assert_eq!(m, "m/ggml-x.bin", "the model argument is exactly what the caller exposed");
    assert!(args.iter().all(|a| a.is_ascii()), "every argument handed to whisper must be ASCII");
    let _ = std::fs::remove_dir_all(d);
}

#[test]
fn no_network_client_exists_in_dependencies_or_speech_sources() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    // Both manifests on the speech path: this crate, and the shared
    // `meb-engines` crate that now holds the engine resolver, the process
    // runner and the bundle verifier.
    for manifest in ["Cargo.toml", "../crates/meb-engines/Cargo.toml"] {
        let cargo = std::fs::read_to_string(root.join(manifest)).unwrap().to_lowercase();
        // Only real dependency lines count: Cargo.toml's comments legitimately *mention* removed crates.
        let deps: String = cargo
            .split("[dependencies]")
            .nth(1)
            .unwrap_or("")
            .split("\n[")
            .next()
            .unwrap_or("")
            .lines()
            .map(|l| l.split('#').next().unwrap_or(""))
            .collect::<Vec<_>>()
            .join("\n");
        for banned in ["reqwest", "hyper", "ureq", "isahc", "attohttpc", "surf", "curl", "tungstenite", "websocket", "tokio-tungstenite", "native-tls", "openssl", "rustls"] {
            assert!(!deps.contains(banned), "network-capable crate in {manifest}: {banned}");
        }
    }
    let files = [
        "src/speech/commands.rs",
        "src/speech/job.rs",
        "src/speech/limits.rs",
        "src/speech/pipeline.rs",
        "src/engines/speech.rs",
        "src/engines/speech_manifest.rs",
        "src/engines/audio_prep.rs",
        "src/engines/audio_wav.rs",
        "src/engines/ffmpeg_manifest.rs",
        "src/engines/resolver.rs",
        // Moved into the shared `meb-engines` crate, still squarely on the
        // speech path: the bundle verifier, the engine identity/error model,
        // the resolution mechanism, and the process runner that is what
        // actually spawns whisper.cpp.
        "../crates/meb-engines/src/bundle.rs",
        "../crates/meb-engines/src/engine_id.rs",
        "../crates/meb-engines/src/error.rs",
        "../crates/meb-engines/src/process.rs",
        "../crates/meb-engines/src/resolver.rs",
    ];
    for f in files {
        let src = std::fs::read_to_string(root.join(f)).unwrap();
        // strip the test module so test fixtures/URLs in string literals don't count
        let prod = src.split("#[cfg(test)]").next().unwrap();
        for banned in ["TcpStream", "UdpSocket", "std::net", "reqwest", "hyper::", "http://", "https://"] {
            assert!(!prod.contains(banned), "{f} contains network-capable code/URL: {banned}");
        }
    }
}

#[test]
fn ffmpeg_argv_locks_the_file_protocol_and_bounds_output() {
    // Static audit of the preprocessing invocation (the source of truth for what runs).
    let src = include_str!("../engines/audio_prep.rs");
    let prod = src.split("#[cfg(test)]").next().unwrap();
    for needle in ["\"-protocol_whitelist\", \"file\"", "spec_rel(", "spec_abs(", "\"-map\", \"0:a:0\"", "\"-vn\"", "\"-nostdin\"", "\"-t\""] {
        assert!(prod.contains(needle), "missing hardening: {needle}");
    }
    assert!(!prod.contains("Command::new(\"cmd") && !prod.contains("powershell"));
}

// ------------------------------------------- human-speech measurement ----------

fn word_error_rate(reference: &str, hypothesis: &str) -> f64 {
    let r: Vec<&str> = reference.split_whitespace().collect();
    let h: Vec<&str> = hypothesis.split_whitespace().collect();
    if r.is_empty() {
        return if h.is_empty() { 0.0 } else { 1.0 };
    }
    let mut prev: Vec<usize> = (0..=h.len()).collect();
    for i in 1..=r.len() {
        let mut cur = vec![i; h.len() + 1];
        for j in 1..=h.len() {
            let sub = prev[j - 1] + usize::from(r[i - 1] != h[j - 1]);
            cur[j] = sub.min(prev[j] + 1).min(cur[j - 1] + 1);
        }
        prev = cur;
    }
    prev[h.len()] as f64 / r.len() as f64
}

/// Measurement, not a pass/fail accuracy gate: point `MEB_HUMAN_SPEECH_DIR` at a folder of
/// `<name>.wav|mp3|...` + `<name>.txt` (reference) pairs. Not run by default.
#[test]
fn measure_word_error_rate_on_human_speech_when_provided() {
    let _serial = real_lock();
    let Ok(dir) = std::env::var("MEB_HUMAN_SPEECH_DIR") else {
        eprintln!("SKIP: set MEB_HUMAN_SPEECH_DIR to measure real-speech accuracy");
        return;
    };
    if !audio_prep_ready() {
        return;
    }
    let Some(engine) = whisper_ready() else { return };
    let mut total_ref = 0usize;
    let mut total_err = 0f64;
    let mut entries: Vec<PathBuf> = std::fs::read_dir(&dir).unwrap().flatten().map(|e| e.path()).collect();
    entries.sort();
    for p in entries {
        let ext = p.extension().and_then(|e| e.to_str()).unwrap_or("").to_lowercase();
        if audio_prep::ACCEPTED_EXTENSIONS.contains(&ext.as_str()) {
            let Ok(reference) = std::fs::read_to_string(p.with_extension("txt")) else { continue };
            let started = std::time::Instant::now();
            let t = run(&p, "tr", &engine).unwrap();
            let (r, h) = (norm(&reference), norm(&t.plain_text()));
            let wer = word_error_rate(&r, &h);
            eprintln!(
                "[{}] {:.1}s  WER={:.0}%\n  REF: {}\n  HYP: {}",
                p.file_name().unwrap().to_string_lossy(),
                started.elapsed().as_secs_f64(),
                wer * 100.0,
                reference.trim(),
                t.plain_text()
            );
            let n = r.split_whitespace().count();
            total_ref += n;
            total_err += wer * n as f64;
        }
    }
    if total_ref > 0 {
        eprintln!("[overall] word error rate (diacritics folded): {:.0}% over {total_ref} reference words", total_err / total_ref as f64 * 100.0);
    }
}

#[test]
fn word_error_rate_helper_is_correct() {
    assert_eq!(word_error_rate("a b c d", "a b c d"), 0.0);
    assert_eq!(word_error_rate("a b c d", "a x c d"), 0.25);
    assert_eq!(word_error_rate("a b c d", "a b"), 0.5);
    assert_eq!(word_error_rate("", ""), 0.0);
}

